  // which recolors page/text and preserves embedded image colors.
  const enabled=()=>!!app.loadLocalStorage("pdfjs-is-themed");
  const applyColors=()=>{
    app.saveLocalStorage("pdfjs-is-themed",plugin.settings.invertPdfColors?"true":null);
    for(const leaf of app.workspace.getLeavesOfType("pdf"))leaf.view.viewer?.child?.onCSSChange();
  };
  plugin.updatePdfColors=applyColors;
