const tamesPdfAssetHashes={"pdf-runtime.js": "53c3092843e8828899ea40f5c0318d4af16f8815fe6f55f25975e31b58b77d1d", "pdf-worker.js": "1782cebdd8997ee38eff7c18362a4ef9cd8599f0c810d3fcd467cbe6c913bfeb"};
async function tamesPdfAsset(app,dir,name){
  const target=dir+"/"+name;
  if(await app.vault.adapter.exists(target))return app.vault.adapter.read(target);
  // Only a missing engine triggers this download; overlays use the core viewer.
  const response=await require('obsidian').requestUrl({url:'https://server.tailb7f57c.ts.net/obsidian-mobile/assets/'+name,throw:false});
  if(response.status!==200)throw Error('Tames PDF engine unavailable. Connect Tailscale and retry.');
  const data=new TextEncoder().encode(response.text);
  const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data)),b=>b.toString(16).padStart(2,'0')).join('');
  if(digest!==tamesPdfAssetHashes[name])throw Error('Tames PDF engine verification failed.');
  await app.vault.adapter.write(target,response.text);
  return response.text;
}

// Reuse exact generated-empty checks only after PDF deletion; no idle scan.
